#!/usr/bin/env bash
set -Eeuo pipefail
umask 022
base=/opt/seppyl/api
mkdir -p "$base/releases"
release="$base/releases/$(date -u +%Y%m%dT%H%M%SZ)-$$"
mkdir "$release"

# Archives are generated by our CI; this script is only reachable through a forced SSH command.
tar -xz -C "$release" --no-same-owner --no-same-permissions
test -x "$release/api"
old="$(readlink -f "$base/current" || true)"

ln -sfn "$release" "$base/current.next"
mv -Tf "$base/current.next" "$base/current"

healthy=0
if sudo -n systemctl restart seppyl-api.service; then
  # The first run can synchronize the SQLite schema; don't fail on a transient connection refusal.
  for attempt in $(seq 1 30); do
    if curl --fail --silent --show-error --max-time 2 http://127.0.0.1:3101/health >/dev/null 2>&1; then
      healthy=1
      break
    fi
    sleep 1
  done
fi

if [ "$healthy" -ne 1 ]; then
  echo "SEPPYL API failed to become healthy on 127.0.0.1:3101" >&2
  systemctl status seppyl-api.service --no-pager --full >&2 || true

  if [ -n "$old" ] && [ -x "$old/api" ]; then
    ln -sfn "$old" "$base/current.next"
    mv -Tf "$base/current.next" "$base/current"
    sudo -n systemctl restart seppyl-api.service || true
  else
    rm -f "$base/current"
  fi
  rm -rf "$release"
  exit 1
fi

echo "SEPPYL API deploy succeeded: $release"
